const paths = {
 home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9', calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 10h18M7 14h2m4 0h2m-8 3h2',
 plan:'m4 7 2 2 4-4m3 2h7M4 15l2 2 4-4m3 2h7', semester:'M4 20V10m5 10V5m5 15V8m5 12V3M2 21h20', spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',
 mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM6 11v1a6 6 0 0 0 12 0v-1M12 18v4m-4 0h8', image:'M3 4h18v16H3ZM3 16l5-5 5 5 3-3 5 5M15 8h.01',
 user:'M8 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0M4 21v-2a8 6 0 0 1 16 0v2Z', arrow:'M5 12h14m-5-5 5 5-5 5', chevron:'m9 5 7 7-7 7', left:'m15 5-7 7 7 7', down:'m5 9 7 7 7-7',
 clock:'M21 12a9 9 0 1 1-18 0 9 9 0 1 1 18 0M12 7v5l3 2', pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0ZM10 10a2 2 0 1 0 4 0 2 2 0 1 0-4 0',
 bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4', close:'m6 6 12 12M18 6 6 18', check:'m5 12 4 4L19 6', settings:'M4 7h16M4 17h16M8 4v6m8 4v6',
 book:'M12 5C9 3 5 3 3 4v16c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v16', school:'m2 9 10-5 10 5-10 5Zm4 3v6l6 3 6-3v-6M22 9v8',
 offline:'m3 3 18 18M8 6a12 12 0 0 1 13 4M3 10l2-1m2 5 2-1m5 0 3 1M11 18h2', send:'m5 12 7-8 7 8M12 4v17', edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4'
};
const icon = (name, cls='') => `<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.spark}"/></svg>`;
const escapeHTML = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=[['today','今日','home'],['calendar','日程','calendar'],['plans','计划','plan'],['semester','学期','semester']];
const initial=()=>({tab:'today',week:4,day:2,view:'week',selectedWeek:4,meeting:false,moved:false,offline:false,modal:null,stage:'input',reminder:'提前30分钟',modules:['plan','deadline','gap','exam'],hidden:[],detail:null,continuePlan:true});
let state=initial(), returnFocus=null, toastTimer, lastText='';
const scrolls={};
const courses=[
 {title:'计算机图形学',short:'图形学',start:'08:00',end:'09:50',place:'莲7号楼 309',type:'course',day:2},
 {title:'概率论',short:'概率论',start:'10:00',end:'11:50',place:'莲4号楼 208',type:'course',day:2},
 {title:'软件工程',short:'软件工程',start:'14:00',end:'15:50',place:'莲7号楼 402',type:'course',day:2},
 {title:'数据库原理',short:'数据库',start:'08:00',end:'09:50',place:'莲6号楼 201',type:'course',day:0},
 {title:'大学英语',short:'英语',start:'10:00',end:'11:50',place:'莲4号楼 205',type:'course',day:1},
 {title:'操作系统',short:'操作系统',start:'10:00',end:'11:50',place:'莲6号楼 405',type:'course',day:3},
 {title:'Python程序设计',short:'Python',start:'14:00',end:'15:50',place:'文科楼 302',type:'course',day:4}
];
function events(){return [...courses,{title:'Java实验报告',short:'报告',start:state.moved?'16:00':'17:00',end:state.moved?'17:00':'18:00',place:'个人学习计划',type:'plan',day:state.moved?3:2},...(state.meeting?[{title:'课题组组会',short:'组会',start:'17:00',end:'18:00',place:'会议室 6412',type:'fixed',day:2}]:[])];}
const fixtureText='周三17点到18点开组会，会议室6412，帮我调整冲突的学习计划。';
function toast(text,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${escapeHTML(text)}</span>${undo?'<button data-action="undo">撤销</button>':''}`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
function goTab(tab){scrolls[state.tab]=$('#app-main').scrollTop;state.tab=tab;render();$('#app-main').scrollTop=scrolls[tab]||0;}
function header(){const copy={today:['9月23日 · 周三 · 第4周','今日安排'],calendar:['2026—2027 第一学期','日程'],plans:['','计划'],semester:['2026—2027 第一学期','本学期']}[state.tab];return `<div class="header-row"><div>${copy[0]?`<div class="eyebrow">${copy[0]}</div>`:''}<h1 class="header-title" style="margin:0">${copy[1]}</h1></div><div class="header-actions">${state.tab==='calendar'?`<button class="round-button" aria-label="导入课表" data-action="schools">${icon('school')}</button>`:''}<button class="avatar" aria-label="账户与设置" data-action="account">${icon('user')}</button></div></div>`;}
function row(e,index=0){const current=e.title==='概率论';const past=e.title==='计算机图形学';return `<button class="course-row ${current?'current':past?'past':''}" data-action="detail" data-title="${escapeHTML(e.title)}"><div class="timepair">${e.start}<small>${e.end}</small></div><i class="rail" style="background:${e.type==='plan'?'#a78ada':e.type==='fixed'?'#d7a26e':'#73b298'}"></i><div><div class="course-title">${e.title}</div><div class="course-meta">${e.place}</div></div><span class="course-state">${e.type==='plan'?'计划':e.type==='fixed'?'活动':current?'进行中':past?'已结束':icon('chevron')}</span></button>`;}
function section(title,action='',label=''){return `<div class="section-head"><h2>${title}</h2>${action?`<button data-action="${action}">${label}</button>`:''}</div>`;}
function today(){const mods={plan:[ 'plan','个人计划',state.moved?'报告已调至周四':'17:00 · Java报告','plans'],deadline:['bell','近期截止','周五 · Java实验报告','plans'],gap:['clock','日程分析','查看本周日程分析','query'],exam:['book','近期考试','暂定第14周 · 待确认','semester']};return `<div class="next-card"><div class="next-top"><span><i class="dot"></i>下一节课</span><span>14:00—15:50</span></div><h2>软件工程</h2><div class="sub">${icon('pin')}<span style="vertical-align:top;margin-left:4px">莲7号楼 402 · 第5—6节</span></div></div>${section('今日课程','calendar','完整日程 '+ '→')}<div class="compact-list">${courses.filter(e=>e.day===2).map(row).join('')}</div><button class="urgent" data-action="${state.meeting&&!state.moved?'replan':'detail'}" data-title="${state.meeting&&!state.moved?'':'Java实验报告'}">${icon(state.meeting&&!state.moved?'calendar':'bell')}<div><b>${state.meeting&&!state.moved?'组会与学习计划重叠':'Java实验报告 · 周五18:00截止'}</b><small>${state.meeting&&!state.moved?'17:00—18:00，查看调整建议':'还需1小时 · 已有一段学习安排'}</small></div>${icon('chevron','chev')}</button>${state.meeting?`<div class="plan-mini">${icon('calendar')}<div><strong>今天还有组会</strong><small>17:00—18:00 · 会议室6412</small></div></div>`:''}${section('快捷查看','customize','自定义')}<div class="module-grid">${state.modules.filter(id=>!state.hidden.includes(id)).map(id=>{const m=mods[id];return `<button class="module" data-action="${m[3]}"><div class="module-icon">${icon(m[0])}</div><b>${m[1]}</b><small>${m[2]}</small></button>`;}).join('')}</div>`;}
function dateFor(week,day){const d=new Date(Date.UTC(2026,7,31+(week-1)*7+day));return `${d.getUTCMonth()+1}/${d.getUTCDate()}`;}
function calendar(){const days='一二三四五六日';const items=state.week===4?events():[];const dayrow=`<div class="days-header"><span></span>${[...days].map((d,i)=>`<button data-action="day" data-day="${i}" class="${state.day===i?'active':''}" aria-label="周${d} ${dateFor(state.week,i)}">${d}<b>${dateFor(state.week,i).split('/')[1]}</b></button>`).join('')}</div>`;return `<div class="view-controls"><div class="week-control"><button aria-label="上一周" data-action="prev-week" ${state.week===1?'disabled':''}>${icon('left')}</button><button data-action="weeks">第${state.week}周 ${icon('down')}</button><button aria-label="下一周" data-action="next-week" ${state.week===20?'disabled':''}>${icon('chevron')}</button></div><button class="back-today" data-action="current-week">回本周</button></div><div class="view-controls"><div class="segmented"><button data-action="view-week" class="${state.view==='week'?'active':''}">周课表</button><button data-action="view-day" class="${state.view==='day'?'active':''}">按天查看</button></div><span class="tiny">${dateFor(state.week,0)}—${dateFor(state.week,6)}</span></div>${state.view==='week'?`<div class="calendar">${dayrow}<div class="grid-body">${Array.from({length:11},(_,i)=>`<span class="hour" style="top:${i*44+4}px">${i+8}:00</span>`).join('')}${Array.from({length:7},(_,i)=>`<i class="grid-line" style="left:calc(27px + (100% - 27px)*${i}/7)"></i>`).join('')}${items.map(e=>{const [h,m]=e.start.split(':').map(Number);const [z,n]=e.end.split(':').map(Number);return `<button aria-label="${escapeHTML(e.title)} 周${days[e.day]} ${e.start}" class="event ${e.type} ${state.meeting&&!state.moved&&e.type==='plan'?'conflict':''}" data-action="detail" data-title="${escapeHTML(e.title)}" style="left:calc(29px + (100% - 27px)*${e.day}/7 ${e.type==='fixed'&&!state.moved?'+ 12px':''});top:${(h-8+m/60)*44}px;height:${(z-h+(n-m)/60)*44-3}px;width:calc((100% - 27px)/7 - ${e.type==='fixed'&&!state.moved?'16':'4'}px)"><b>${e.short}</b><span>${e.start}</span></button>`;}).join('')}</div></div><div class="legend"><span><i style="background:#74b298"></i>课程</span><span><i style="background:#d4a26d"></i>固定日程</span><span><i style="background:#a98adc"></i>个人计划</span></div>${!items.length?'<p class="tiny">此原型只预置第4周数据，可点“回本周”。</p>':''}`:`<div class="calendar">${dayrow}</div><h2 class="day-date">${dateFor(state.week,state.day)} 周${days[state.day]}的完整安排</h2><div class="compact-list">${items.filter(e=>e.day===state.day).sort((a,b)=>a.start.localeCompare(b.start)).map(row).join('')||'<div class="empty">这一天没有预置安排</div>'}</div>${state.day===4&&state.week===4?'<div class="urgent"><div><b>18:00 · Java实验报告截止</b></div></div>':''}`}<button class="nav-row" data-action="query">${icon('spark')}分析本周日程${icon('chevron')}</button>`;}
function plans(){return `<div class="view-controls"><div class="segmented"><button class="active" data-action="plans">进行中</button><button data-action="history">完成记录</button></div><button class="back-today" data-action="availability">可学习时间</button></div>${state.meeting&&!state.moved?'<div class="offline">17:00的计划与新组会重叠，需要调整。</div>':''}<div class="task-card"><div class="task-top"><h3>Java实验报告</h3><button aria-label="查看Java实验报告" data-action="detail" data-title="Java实验报告">${icon('chevron')}</button></div><div class="task-meta"><span class="tag" style="background:var(--peach);color:var(--orange)">周五18:00截止</span><span class="tag" style="background:#f0f1f6">还需1小时</span></div><div class="task-foot"><span>剩余工作：1小时 · 已安排：1小时</span><span>${state.meeting&&!state.moved?'有冲突':'时间已安排'}</span></div><div class="plan-mini">${icon('clock')}<div><strong>${state.moved?'周四 16:00—17:00':'周三 17:00—18:00'}</strong><small>${state.moved?'已调整，未与组会重叠':'已安排1小时'}</small></div></div>${state.moved?'<button class="caption-link" data-action="undo">撤销这次调整</button>':''}</div><button class="primary" data-action="replan">${icon('spark')} 安排任务</button>${section('待安排')}<div class="card"><b style="font-size:13px">概率论复习</b><p class="tiny" style="margin-top:8px">考试暂定第14周，尚未安排复习。</p><button class="caption-link" data-action="agent">安排复习 →</button></div>`;}
function semester(){return `<div class="card"><div class="semester-progress"><div class="number">第4周</div><div><b style="font-size:13px">本学期共20周</b><p>8月31日开学</p></div></div><div class="week-band">${Array.from({length:20},(_,i)=>`<button class="${[13].includes(i)?'busy ':''}${state.selectedWeek===i+1?'selected':''}" data-action="semester-week" data-week="${i+1}" aria-label="查看第${i+1}周">${i+1}</button>`).join('')}</div></div>${section(`第${state.selectedWeek}周的事项`)}<div class="timeline">${state.selectedWeek===4?`${state.meeting?'<div class="node fixed"><div class="date">9月23日 · 周三 17:00</div><h3>课题组组会</h3><p>会议室6412 · 已确认</p></div>':''}<div class="node"><div class="date">9月25日 · 周五 18:00</div><h3>Java实验报告截止</h3><p>还需1小时，${state.moved?'周四已安排':'周三已安排'}</p></div>${state.meeting&&!state.moved?'<div class="node"><div class="date">9月23日 · 周三 17:00—18:00</div><h3>组会与报告计划重叠</h3><button class="caption-link" data-action="replan">调整报告计划 →</button></div>':''}`:state.selectedWeek===14?'<div class="node"><div class="date">第14周 · 日期待确认</div><h3>概率论考试</h3><p>具体日期尚未公布</p></div>':'<div class="node"><h3>这一周暂无事项</h3></div>'}</div>${section('学期管理')}<button class="nav-row" data-action="exam">${icon('book')} 考试与复习 ${icon('chevron')}</button><button class="nav-row" data-action="courses">${icon('school')} 课程列表 ${icon('chevron')}</button><button class="nav-row" data-action="schools">${icon('calendar')} 导入或更新课表 ${icon('chevron')}</button>`;}
function render(){const main=$('#app-main'),oldScroll=main.scrollTop;$('#app-header').innerHTML=header();main.innerHTML=`${state.offline?`<div class="offline">${icon('offline')}正在查看本机记录，恢复联网后更新。</div>`:''}<div class="page">${({today,calendar,plans,semester}[state.tab])()}</div>`;main.scrollTop=oldScroll;$('#ai-dock').innerHTML=`<div class="ai-entry"><button class="agent-label" data-action="agent"><span class="spark">${icon('spark')}</span><span class="label">记录日程，或向AI提问</span></button><button class="mic" data-action="voice" aria-label="直接语音输入">${icon('mic')}</button></div>`;$('#bottom-nav').innerHTML=tabs.map(([id,label,i])=>`<button class="${state.tab===id?'active':''}" data-action="${id}" aria-current="${state.tab===id?'page':'false'}">${icon(i)}<span>${label}</span></button>`).join('');$('.screen-links').innerHTML=tabs.map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-action="${id}">${label}</button>`).join('');const notes={today:['今日页面','展示下一节课、今日课程与近期截止事项。'],calendar:['日程页面','查看课程、固定活动与个人计划。周视图和按天查看保留同一选中日期。'],plans:['计划页面','展示任务截止时间、剩余工作量和已安排的时段。'],semester:['学期页面','选择周次，查看这一周的考试、截止事项与日程变化。']}[state.tab];$('#note-title').textContent=notes[0];$('#note-copy').textContent=notes[1];$('.state-toggle').textContent=state.offline?'恢复在线状态':'体验离线状态';}
function openModal(type,stage){returnFocus=document.activeElement;state.modal=type;if(stage)state.stage=stage;drawModal();}
function closeModal(){state.modal=null;$('#overlay').hidden=true;$('#overlay').innerHTML='';['#app-header','#app-main','#ai-dock','#bottom-nav'].forEach(s=>$(s).inert=false);if(returnFocus?.isConnected)returnFocus.focus();else $('.agent-label').focus();}
function showSheet(title,body){$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="sheet-body">${body}</div></section>`;['#app-header','#app-main','#ai-dock','#bottom-nav'].forEach(s=>$(s).inert=true);$('.close').focus();}
function agentBody(){switch(state.stage){case 'input':return `<div class="input-box"><textarea id="prompt" aria-label="告诉AI你的需求" placeholder="例如：周三加了组会，帮我调整冲突的计划">${escapeHTML(lastText)}</textarea><div class="input-tools"><button data-action="image" aria-label="添加通知图片">${icon('image')}</button><button data-action="voice" aria-label="语音输入">${icon('mic')}</button><span class="tiny">文字、图片或语音</span><button class="send" aria-label="发送" data-action="send">${icon('send')}</button></div></div><div class="examples"><button data-action="example-meeting">${icon('calendar')} 示例：添加组会并调整计划</button><button data-action="query">${icon('spark')} 这周有时间冲突吗？</button></div><button class="text-button" data-action="manual">直接手工填写</button><p class="footnote">原型使用固定示例；自由对话和真实识别尚未接入。</p>`;
 case 'candidate':return `<div class="source"><strong>通知原文</strong>${escapeHTML(lastText||fixtureText)}</div><div class="card"><span class="request-tag">新增日程</span><h3 style="font-size:20px">课题组组会</h3><div class="detail-rows"><div class="detail-row"><span>时间</span><b>9月23日 周三<br>17:00—18:00</b></div><div class="detail-row"><span>地点</span><b>会议室6412</b></div><div class="detail-row"><span>提醒</span><button class="caption-link" data-action="reminder">${state.reminder} · 修改</button></div></div><p class="footnote">“周三”按原消息日期9月23日、北京时间解释。</p></div><div class="offline">与Java报告的个人计划重叠1小时。加入后可调整。</div><button class="primary" data-action="save-meeting">加入日程</button><button class="text-button" data-action="input-again">返回修改原文</button>`;
 case 'saved':return `<div class="confirmed">${icon('check')}组会已加入日程 · ${state.reminder}提醒</div><h3 style="font-size:19px;margin-bottom:10px">有一段个人计划需要调整</h3><p>组会占用了周三17:00—18:00，原定的Java报告与它重叠。</p><button class="primary" data-action="proposal">查看调整方案</button><button class="text-button" data-action="view-calendar">先看日程</button>`;
 case 'proposal':return `<div class="confirmed">${icon('check')}组会已保存，下面只调整个人计划</div><div class="card"><div class="task-top"><h3>Java实验报告</h3><span class="tag" style="background:var(--lilac);color:var(--purple)">1小时</span></div><div class="change-old"><span>原</span><span>周三 17:00—18:00</span></div><div class="change-arrow">↓</div><div class="change-new"><span>新</span><span>周四 16:00—17:00</span></div><div class="reason">避开组会，使用已设置的可学习时段。仍在周五18:00截止前，其他安排保持不变。</div></div><p class="provenance">依据：本周课程、组会、个人计划与可学习时间。</p><button class="primary" data-action="apply">应用调整</button><div class="action-row"><button class="secondary" data-action="alternative">这个时间不合适</button><button class="secondary" data-action="close">暂不调整</button></div>`;
 case 'alternative':return `<h3 style="margin-bottom:10px">更换时间</h3><p>真实版本会根据你的补充重新查询空档。本原型仅预置周四16:00—17:00的调整方案，不虚构其他可用时段。</p><div class="input-box"><textarea aria-label="补充安排偏好" placeholder="例如：周四下午也有事，尽量安排在周五上午"></textarea></div><div class="action-row"><button class="secondary" data-action="proposal">回到原方案</button><button class="primary" data-action="close">保留当前安排</button></div>`;
 case 'receipt':return `<div class="receipt"><div class="done">${icon('check')}</div><div><h3>计划已调整</h3><p>仅移动1段计划，组会与课程保持不变。</p></div></div><div class="card"><b>Java实验报告</b><div class="detail-row"><span>新的安排</span><b>周四 16:00—17:00</b></div><div class="detail-row"><span>组会</span><b>周三 17:00—18:00</b></div></div><button class="primary" data-action="view-calendar">在日程中查看</button><button class="text-button" data-action="undo">撤销本次计划调整</button>`;
 case 'query':return `<span class="request-tag">依据已记录日程 · 第4周</span><h3 style="font-size:20px;margin-bottom:12px">${state.meeting&&!state.moved?'发现1处时间冲突':'本周暂无时间冲突'}</h3><p>${state.meeting&&!state.moved?'组会与Java报告计划重叠。课程本身没有冲突，建议只移动这一段个人计划。':state.moved?'组会和Java报告已错开，目前预置日程中没有重叠。报告安排在周四，仍早于周五截止。':'周三有3次课程，下午15:50结束，17:00有一小时报告计划。15:50—17:00没有已记录的安排。'}</p><div class="query-stat"><div><b>3次</b><small>周三课程</small></div><div><b>${state.meeting&&!state.moved?'1段':'0段'}</b><small>重叠的个人计划</small></div></div><p class="provenance">根据原型预置课程与个人计划计算；没有实际完成记录，不评价真实学习效率。</p><button class="primary" data-action="${state.meeting&&!state.moved?'proposal':'view-calendar'}">${state.meeting&&!state.moved?'查看调整方案':'查看完整日程'}</button>`;
 case 'voice':case 'image':return `<div class="receipt"><div class="done" style="background:var(--lilac);color:var(--purple)">${icon(state.stage==='voice'?'mic':'image')}</div><div><h3>${state.stage==='voice'?'语音输入':'图片录入'}</h3></div></div><p>正式版本会先${state.stage==='voice'?'录音并转写':'识别图片文字'}，你可以校对后继续。原型不调用麦克风、不读取或上传文件。</p><button class="primary" data-action="example-meeting">用示例通知继续体验</button><button class="text-button" data-action="input-again">返回文字输入</button>`;
 case 'unsupported':return `<p>这份原型没有接入真实AI，不会把任意输入都伪装为识别成功。你的文字仍保留在输入框。</p><button class="primary" data-action="example-meeting">体验预置的组会通知</button><button class="text-button" data-action="input-again">返回编辑</button>`;
 }}
function drawModal(){if(state.modal==='agent'){showSheet(['proposal','alternative'].includes(state.stage)?'调整计划':state.stage==='candidate'?'确认日程':'AI助手',agentBody());return;}
 if(state.modal==='schools'){showSheet('选择学校',`<p>课表从学校原站导入，先选你所在的学校。</p><input class="search" id="school-search" aria-label="搜索学校" placeholder="搜索学校"><div id="school-results">${schoolResult()}</div><p class="footnote">目前仅适配河南工业大学。找不到学校时，可以先手工添加课程。</p><button class="text-button" data-action="manual-course">手工添加课程</button>`);return;}
 if(state.modal==='school-login'){showSheet('河南工业大学',`<div class="source">jwglxt.haut.edu.cn · 学校原站</div><p>正式App会在此打开教务登录页面。登录后读取课表，预览并确认导入。</p><p class="footnote">原型不连接教务系统，不收集账号或密码。</p><button class="primary" data-action="schools">返回学校选择</button>`);return;}
 if(state.modal==='weeks'){showSheet('选择周次',`<p>当前学期共20周，本周是第4周。</p><div class="choice-week">${Array.from({length:20},(_,i)=>`<button data-action="pick-week" data-week="${i+1}" class="${state.week===i+1?'active':''}">${i+1}周</button>`).join('')}</div>`);return;}
 if(state.modal==='customize'){const names={plan:'今日个人计划',deadline:'近期截止',gap:'日程分析',exam:'近期考试'};showSheet('首页模块',`<p>课程与紧急事项始终显示。下面的模块可以隐藏或上移。</p>${state.modules.map((id,i)=>`<div class="toggle-row"><input type="checkbox" id="mod-${id}" data-module="${id}" ${state.hidden.includes(id)?'':'checked'}><label for="mod-${id}">${names[id]}</label><button class="up" data-action="module-up" data-module="${id}" aria-label="上移${names[id]}" ${i===0?'disabled':''}>↑</button></div>`).join('')}<div class="action-row"><button class="secondary" data-action="module-reset">恢复默认</button><button class="primary" data-action="close">完成</button></div>`);return;}
 if(state.modal==='detail'){const e=events().find(e=>e.title===state.detail);showSheet(state.detail||'事项详情',e?`<span class="request-tag">${e.type==='course'?'课程 · 固定安排':e.type==='fixed'?'活动 · 固定日程':'个人学习计划'}</span><div class="detail-rows"><div class="detail-row"><span>时间</span><b>周${'一二三四五六日'[e.day]} ${e.start}—${e.end}</b></div><div class="detail-row"><span>地点</span><b>${e.place}</b></div>${e.type==='plan'?'<div class="detail-row"><span>截止</span><b>周五18:00</b></div>':''}<div class="detail-row"><span>来源</span><b>${e.type==='course'?'教务课表':e.type==='fixed'?'刚才录入的通知':'个人安排'}</b></div><div class="detail-row"><span>提醒</span><b>${e.type==='fixed'?state.reminder:'提前15分钟'}</b></div></div><button class="primary" data-action="agent">${icon('spark')} 让AI修改</button>`:'<p>该事项未在本原型预置。</p>');return;}
 if(state.modal==='reminder'){showSheet('什么时候提醒',`<div class="editor"><label>提前时间<select id="reminder-value"><option ${state.reminder==='提前30分钟'?'selected':''}>提前30分钟</option><option ${state.reminder==='提前1小时'?'selected':''}>提前1小时</option><option ${state.reminder==='提前1天'?'selected':''}>提前1天</option></select></label></div><button class="primary" data-action="save-reminder">确认提醒</button>`);return;}
 if(state.modal==='manual'){showSheet('手工记录',`<p>这里展示表单层级。原型仅保留标题为输入草稿，不保存日程或提交到账号。</p><div class="editor"><label>标题<input id="manual-title" placeholder="想记下什么"></label><label>日期<input type="date" value="2026-09-23"></label><label>时间<input type="time" value="17:00"></label></div><button class="primary" data-action="manual-save">保留标题草稿</button>`);return;}
 const bodies={account:['账户与设置',`<div class="nav-row">${icon('user')}个人账号 · 原型示意</div><button class="nav-row" data-action="schools">${icon('school')}学校与课表导入 ${icon('chevron')}</button><button class="nav-row" data-action="availability">${icon('clock')}可学习时间 ${icon('chevron')}</button><button class="nav-row" data-action="customize">${icon('settings')}首页模块 ${icon('chevron')}</button><button class="nav-row" data-action="offline">${icon('offline')}${state.offline?'恢复在线':'体验离线状态'} ${icon('chevron')}</button><p class="footnote">本页为V2设计原型，没有连接真实账号。</p>`],availability:['可学习时间',`<p>AI会在以下时段内安排任务。</p><div class="card"><div class="detail-row"><span>周三</span><b>17:00—18:00</b></div><div class="detail-row"><span>周四</span><b>16:00—17:00</b></div></div><p>本原型用这些固定时段核对组会后的调整方案。</p><button class="primary" data-action="agent">修改可学习时间</button>`],history:['完成记录','<div class="empty">暂无完成记录</div>'],exam:['考试与复习','<div class="card"><h3>概率论考试</h3><p style="margin-top:10px">暂定第14周 · 日期待确认</p></div><p>具体日期公布后可更新考试时间。</p>'],courses:['课程列表',`<div class="compact-list">${courses.slice(0,3).map(row).join('')}</div>`],'manual-course':['手工添加课程','<p>正式App保留手工添加课程的能力。此原型只展示入口层级，不填写或保存真实课表。</p><button class="primary" data-action="schools">返回学校选择</button>']};const entry=bodies[state.modal];if(entry)showSheet(entry[0],entry[1]);}
function schoolResult(){return `<button class="school" data-action="school-login"><span class="school-icon">${icon('school')}</span><span><b>河南工业大学</b><small>已适配 · 正方教务系统</small></span>${icon('chevron')}</button>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(tabs.some(t=>t[0]===a)){if(state.modal)closeModal();goTab(a);return;}switch(a){case 'reset':state=initial();lastText='';Object.keys(scrolls).forEach(k=>delete scrolls[k]);closeModal();render();$('#app-main').scrollTop=0;toast('体验已重置');break;
 case 'close':closeModal();break;case 'agent':openModal('agent','input');break;case 'input-again':state.stage='input';state.modal='agent';drawModal();break;
 case 'example-meeting':lastText=fixtureText;state.modal='agent';state.stage=state.meeting?(state.moved?'receipt':'proposal'):'candidate';drawModal();break;
 case 'send':lastText=$('#prompt').value.trim();if(!lastText){toast('先写下你的需求');return;}if(state.offline){toast('离线时先保留文字，联网后再交给AI');return;}state.stage=lastText===fixtureText?(state.meeting?'proposal':'candidate'):'unsupported';drawModal();break;
 case 'save-meeting':if(state.offline){toast('尚未联网，候选仍保留');return;}state.meeting=true;state.stage='saved';render();drawModal();break;
 case 'proposal':state.modal='agent';state.stage=state.offline?'input':state.moved?'receipt':'proposal';drawModal();if(state.offline)toast('联网后才能生成新的调整建议');break;
 case 'apply':if(state.offline){toast('未应用，联网后再试');return;}state.moved=true;state.stage='receipt';render();drawModal();toast('已调整1段个人计划',true);break;
 case 'undo':if(state.offline){toast('联网后才能撤销调整');return;}state.moved=false;closeModal();render();toast('已撤销计划调整，组会仍保留');break;
 case 'alternative':state.stage='alternative';drawModal();break;
 case 'view-calendar':closeModal();state.week=4;state.day=state.moved?3:2;state.view='day';goTab('calendar');break;
 case 'query':if(state.offline){toast('当前离线，暂不生成分析结论');return;}openModal('agent','query');break;
 case 'voice':case 'image':lastText=$('#prompt')?.value||lastText;openModal('agent',a);break;
 case 'replan':if(state.offline){toast('联网后再分析，现有安排仍可查看');return;}openModal('agent',state.meeting?(state.moved?'receipt':'proposal'):'input');break;
 case 'prev-week':state.week=Math.max(1,state.week-1);render();break;case 'next-week':state.week=Math.min(20,state.week+1);render();break;case 'current-week':state.week=4;state.day=2;render();break;
 case 'view-week':state.view='week';render();break;case 'view-day':state.view='day';render();break;case 'day':state.day=Number(b.dataset.day);render();break;
 case 'pick-week':state.week=Number(b.dataset.week);closeModal();render();break;case 'semester-week':state.selectedWeek=Number(b.dataset.week);render();break;
 case 'detail':state.detail=b.dataset.title;openModal('detail');break;
 case 'module-up':{const id=b.dataset.module,i=state.modules.indexOf(id);if(i>0)[state.modules[i-1],state.modules[i]]=[state.modules[i],state.modules[i-1]];render();drawModal();break;}
 case 'module-reset':state.modules=initial().modules;state.hidden=[];render();drawModal();break;
 case 'offline':state.offline=!state.offline;render();if(state.modal)drawModal();toast(state.offline?'离线体验：显示本机安排':'已恢复在线体验');break;
 case 'save-reminder':state.reminder=$('#reminder-value').value;state.modal='agent';state.stage='candidate';drawModal();break;
 case 'manual-save':{const text=$('#manual-title').value.trim();if(!text){toast('请填写标题');return;}lastText=text;closeModal();toast('文字已保留在智能输入草稿中');break;}
 default:openModal(a);
 }});
document.addEventListener('input',e=>{if(e.target.id==='school-search'){const value=e.target.value.trim();$('#school-results').innerHTML=!value||'河南工业大学'.includes(value)?schoolResult():'<div class="empty">暂未适配这所学校</div>';}});
document.addEventListener('change',e=>{const id=e.target.dataset.module;if(id){state.hidden=e.target.checked?state.hidden.filter(v=>v!==id):[...state.hidden,id];render();}});
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const focusable=[...$('#overlay').querySelectorAll('button:not([disabled]),textarea,input,select')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal();});
render();
